<?php declare(strict_types=1);
$memberProfileViewMessages=$managerLanguageMessages??[];
$memberProfileText=static fn(string $source,array $values=[]):string=>\Kulturhus\Native\Language\MemberProfileMessages::text($source,$memberProfileViewMessages,$values);

$memberRates=\Kulturhus\Verein\ContributionRates::all($db,\Kulturhus\Verein\Permissions::actor($db,(string)$_SESSION['actor'])['club_id']);
$singleRate=\Kulturhus\Verein\ContributionRates::label($memberRates['single']['amount_cents']);
$familyRate=\Kulturhus\Verein\ContributionRates::label($memberRates['family']['amount_cents']);
$family=$registry->family($profile['id']);
$restoreFamily=input($_POST,'id')===$profile['id']&&input($_POST,'action')==='save-family';
$restoreAssignment=input($_POST,'id')===$profile['id']&&input($_POST,'action')==='assign-family';
$restoreContribution=input($_POST,'id')===$profile['id']&&input($_POST,'action')==='annual-contribution';
?>
<section class="member-family" data-member-family>
 <h3><?= e($memberProfileText('Familie')) ?> & <?= e($memberProfileText('Beitrag')) ?></h3>
 <?php if($family): ?>
  <div class="member-family-overview"><strong><?= e($family['name']) ?></strong><p><?= $familyRate ?> <?= e($memberProfileText('jährlich für die gesamte Familie · Beitragszahler:')) ?> <strong><?= e($family['payer_name']) ?></strong></p><ul><?php foreach($family['people'] as $person): ?><li><a href="<?= e(url(['view'=>'members','id'=>$person['id']])) ?>"><?= e($person['name']) ?></a><?= e($person['id']===$family['payer_contact_id']?$memberProfileText(' · Beitragszahler'):'') ?></li><?php endforeach ?></ul><p class="muted"><?= e($memberProfileText('Für die zugeordneten Familienmitglieder fällt kein zusätzlicher Einzelbeitrag an.')) ?></p></div>
  <?php if($canAdmissions): ?><p><a class="btn btn-outline theme-secondary button secondary" href="<?= e(url(['view'=>'portal','tab'=>'application','manual'=>'1','family'=>$family['id']])) ?>"><?= e($memberProfileText('Weiteres Familienmitglied aufnehmen')) ?></a></p><?php endif ?>
  <details class="member-profile-inline" <?= $restoreFamily?'open':'' ?>><summary><?= e($memberProfileText('Familienname oder Beitragszahler ändern')) ?></summary>
   <form method="post"><?= csrf().hidden('action','save-family').hidden('id',$profile['id']).hidden('version',$restoreFamily?input($_POST,'version'):$family['version']) ?><div class="form-grid"><label><?= e($memberProfileText('Familienname')) ?><input class="form-control" name="family_name" required maxlength="200" value="<?= e($restoreFamily?input($_POST,'family_name'):$family['name']) ?>"></label><label><?= e($memberProfileText('Beitragszahler')) ?><select class="form-control" name="payer"><?php foreach($family['people'] as $person): ?><option value="<?= e($person['id']) ?>" <?= $person['id']===($restoreFamily?input($_POST,'payer'):$family['payer_contact_id'])?'selected':'' ?>><?= e($person['name']) ?></option><?php endforeach ?></select></label></div><button class="btn btn-solid theme-primary"><?= e($memberProfileText('Familie speichern')) ?></button></form>
  </details>
 <?php else: ?><div class="member-family-overview"><strong><?= e(!empty($memberships)?$memberProfileText('Einzelmitgliedschaft'):$memberProfileText('Keine Familienzuordnung')) ?></strong><p><?= e(!empty($memberships)?$memberProfileText('Beitrag {amount} jährlich',['amount'=>$singleRate]):$memberProfileText('Dieser Kontakt hat noch keine Mitgliedschaft.')) ?></p></div><?php endif ?>
 <details class="member-profile-inline" <?= $restoreAssignment?'open':'' ?>><summary><?= e($memberProfileText('Familienzuordnung ändern')) ?></summary>
  <form method="post"><?= csrf().hidden('action','assign-family').hidden('id',$profile['id']).hidden('expected_family',$restoreAssignment?input($_POST,'expected_family'):($family['id']??'')) ?><div class="form-grid"><label><?= e($memberProfileText('Zuordnung')) ?><select class="form-control" name="family"><option value=""><?= e($memberProfileText('Keine Familie / Einzelmitgliedschaft')) ?></option><option value="new" <?= $restoreAssignment&&input($_POST,'family')==='new'?'selected':'' ?>><?= e($memberProfileText('Neue Familie anlegen (diese Person zahlt)')) ?></option><?php foreach($registry->families() as $option): ?><option value="<?= e($option['id']) ?>" <?= ($restoreAssignment?input($_POST,'family'):($family['id']??''))===$option['id']?'selected':'' ?>><?= e($option['name'].' · '.$option['payer_name']) ?></option><?php endforeach ?></select></label><label><?= e($memberProfileText('Name bei neuer Familie')) ?><input class="form-control" name="family_name" maxlength="200" placeholder="<?= e($memberProfileText('Familie …')) ?>" value="<?= e($restoreAssignment?input($_POST,'family_name'):'') ?>"></label></div><p class="muted"><?= e($memberProfileText('Jede Person behält ihr eigenes Profil und ihre Mitgliedsnummer.')) ?></p><button class="btn btn-solid theme-primary"><?= e($memberProfileText('Zuordnung speichern')) ?></button></form>
 </details>
 <?php if(!empty($memberships)&&$finance->canWrite()): ?><details class="member-profile-inline" <?= $restoreContribution?'open':'' ?>><summary><?= e($memberProfileText('Jahresbeitrag anlegen')) ?></summary><p><?= e($memberProfileText('Erstellt eine offene Beitragsforderung. Wenn für das Jahr bereits eine Forderung besteht, wird diese geöffnet.')) ?></p><form method="post"><?= csrf().hidden('action','annual-contribution').hidden('id',$profile['id']).hidden('expected_family',$restoreContribution?input($_POST,'expected_family'):($family['id']??'')) ?><label><?= e($memberProfileText('Beitragsjahr')) ?><input class="form-control" name="year" type="number" min="2020" max="<?= (int)date('Y')+1 ?>" value="<?= e($restoreContribution?input($_POST,'year'):(string)date('Y')) ?>" required></label><button class="btn btn-solid theme-primary"><?= e($memberProfileText('Jahresbeitrag {amount} zuordnen',['amount'=>$family?$memberProfileText('{amount} für die Familie',['amount'=>$familyRate]):$singleRate])) ?></button></form><p class="muted"><?= e($memberProfileText('Den tatsächlichen Zahlungseingang ordnen Sie anschließend in Finanzen zu.')) ?></p></details><?php endif ?>
</section>
